// UL is the upgrade points spent on the piece, as in the wiki's "Increases Light ATK by UL/2".
// Data generated by `scripts/build-item-effects.mjs`.
import type { ArmorUpgradePoints, ElementKey, ResistKey, StatKey, TetraAlignment, WeaponUpgradePoints } from '../types';
import content from '../data/content/item-effects.json';

export interface ItemEffectValue {
  /** `setStat` replaces the stat outright (Contract of Blood: "your STR becomes equal to its LV"). */
  kind: 'stat' | 'buffStat' | 'setStat' | 'derived' | 'elementalAttack' | 'resistance';
  key: string;
  base: number;
  ulMultiplier: number;
  /** Top of a wiki rolled range ("+2-4 CEL"); each dropped copy rolls once and keeps it. */
  rollMax?: number;
  /** Label for a manually selected battle-state value rather than an item roll. */
  controlLabel?: string;
  /** Written for a Fire alignment; the item's chosen crystal decides the real element or stat. */
  tetra?: boolean;
  /** Added per character level ("+1 per 5 character levels" is 0.2). */
  perLevel?: number;
  min?: number;
  /** Added per piece of the set equipped ("+(10 x total number of this set's items equipped) HP"). */
  perPiece?: number;
}

export const isTetraItem = (effects: ItemEffect[]) => effects.some(effect => effect.effects.some(value => value.tetra));

export interface ItemEffect {
  name: string;
  description: string;
  /** `conditional` is gated on something the calculator cannot see; `reference` carries no numbers. */
  applies: 'always' | 'conditional' | 'reference';
  effects: ItemEffectValue[];
  /** Switching it on ends the item's other exclusive effects (the Magical Gauntlet's shields). */
  exclusive?: boolean;
  /** The skill this line belongs to, when the item grants one. */
  grants?: string;
  /** The skill's "Grants Skill" header or its cost line; neither carries a bonus. */
  role?: 'skill' | 'cost';
  /** A weapon special's skills, split from its text; one special can grant two (Tricky Yoyo). */
  skills?: Array<{ name: string; cost: string | null; text: string }>;
  /** Set thresholds only: the pieces needed, and what the threshold does to outgoing damage. */
  count?: number;
  damagePercent?: number;
  resistanceIgnored?: { types: string[]; percent: number };
}

const WEAPON_EFFECTS = content.weapons as Record<string, ItemEffect[]>;
const ARMOR_EFFECTS = content.armors as Record<string, ItemEffect[]>;
const GEAR_EFFECTS = content.gear as Record<string, ItemEffect[]>;
const SET_EFFECTS = content.sets as Record<string, ItemEffect[]>;

export function setEffects(name: string | null | undefined): ItemEffect[] {
  return (name && SET_EFFECTS[name]) || [];
}

export function weaponEffects(name: string | null | undefined): ItemEffect[] {
  return (name && WEAPON_EFFECTS[name]) || [];
}

export function armorEffects(name: string | null | undefined): ItemEffect[] {
  return (name && ARMOR_EFFECTS[name]) || [];
}

/** The wiki gives these slots no stat columns, so they contribute only through effects. */
export function gearEffects(name: string | null | undefined): ItemEffect[] {
  return (name && GEAR_EFFECTS[name]) || [];
}

/** The wiki's UL is one number; the calculator's per-channel points are summed. */
export function weaponUL(points: WeaponUpgradePoints | undefined): number {
  if (!points) return 0;
  return points.power + points.critical + points.accuracy + points.durability;
}

export function armorUL(points: ArmorUpgradePoints | undefined): number {
  if (!points) return 0;
  // Three channels: a torso has no durability track.
  return points.armor + points.magicArmor + points.evade;
}

export function valueAtUL(value: ItemEffectValue, ul: number, roll?: number, level = 0, pieces = 0): number {
  const rolled = value.rollMax === undefined ? value.base : clampRoll(value, roll);
  const scaled = rolled + ul * value.ulMultiplier + level * (value.perLevel ?? 0) + pieces * (value.perPiece ?? 0);
  return Math.max(value.min ?? -Infinity, Math.floor(scaled));
}

export function clampRoll(value: ItemEffectValue, roll: number | undefined): number {
  if (value.rollMax === undefined) return value.base;
  if (roll === undefined || !Number.isFinite(roll)) return value.base;
  return Math.min(Math.max(Math.floor(roll), value.base), value.rollMax);
}

/** Per value, not per effect: Bands of the Crocodile is "+1-3 WIL, +1-2 DEF". */
export function itemRollKey(itemName: string, effectIndex: number, valueIndex: number): string {
  return `${itemConditionalKey(itemName, effectIndex)}:${valueIndex}`;
}

export interface ItemBonuses {
  stats: Partial<Record<StatKey, number>>;
  /** Final values that replace a stat while their effect is on. */
  setStats: Partial<Record<StatKey, number>>;
  derived: Record<string, number>;
  elementalAttack: Partial<Record<ElementKey, number>>;
  /** Armour text is not read for these; its curated resistance map already applies them. */
  resistances: Partial<Record<ResistKey, number>>;
}

const EMPTY: ItemBonuses = { stats: {}, setStats: {}, derived: {}, elementalAttack: {}, resistances: {} };
const NO_ROLLS: Record<string, number> = Object.freeze({});

const effectsByName = (itemName: string): ItemEffect[] =>
  GEAR_EFFECTS[itemName] ?? WEAPON_EFFECTS[itemName] ?? ARMOR_EFFECTS[itemName] ?? SET_EFFECTS[itemName] ?? [];

// FNV-1a: short, stable and dependency-free.
function lineHash(text: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index++) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(36);
}

const lineKeyCache = new Map<string, string[]>();

function lineKeys(itemName: string): string[] {
  const cached = lineKeyCache.get(itemName);
  if (cached) return cached;
  const repeats = new Map<string, number>();
  const keys = effectsByName(itemName).map(effect => {
    const hash = lineHash(effect.description);
    const seen = repeats.get(hash) ?? 0;
    repeats.set(hash, seen + 1);
    return `${itemName}#${hash}${seen ? `.${seen}` : ''}`;
  });
  lineKeyCache.set(itemName, keys);
  return keys;
}

/** Keyed by the line's text, not its position, so a wiki edit that adds or reorders lines can't move a saved switch. */
export function itemConditionalKey(itemName: string, index: number): string {
  return lineKeys(itemName)[index] ?? `${itemName}#${index}`;
}

/** Positional keys from before 0.9.3 ("Name:5", rolls "Name:5:0") resolve against the current lines. */
export function migrateItemKey(key: string): string {
  if (key.includes('#')) return key;
  const roll = /^(.+):(\d+):(\d+)$/.exec(key);
  if (roll && effectsByName(roll[1]).length) return itemRollKey(roll[1], Number(roll[2]), Number(roll[3]));
  const line = /^(.+):(\d+)$/.exec(key);
  if (line && effectsByName(line[1]).length) return itemConditionalKey(line[1], Number(line[2]));
  return key;
}

export function exclusiveRivals(conditionalKey: string): string[] {
  const itemName = conditionalKey.slice(0, conditionalKey.lastIndexOf('#'));
  const effects = effectsByName(itemName);
  const index = lineKeys(itemName).indexOf(conditionalKey);
  if (!effects[index]?.exclusive) return [];
  return effects.flatMap((effect, other) => (effect.exclusive && other !== index ? [itemConditionalKey(itemName, other)] : []));
}

// The wiki's swap list: "Fire & STR, Ice & SKI, Earth & DEF and Wind & CEL" (Burn, Frostbite, Poison, Confusion).
export const TETRA_PAIRS: Record<TetraAlignment, { stat: StatKey; status: string }> = {
  Fire: { stat: 'str', status: 'Burn' },
  Ice: { stat: 'ski', status: 'Frostbite' },
  Earth: { stat: 'def', status: 'Poison' },
  Wind: { stat: 'cel', status: 'Confusion' },
};

function effectKey(value: ItemEffectValue, tetra: TetraAlignment = 'Fire'): string {
  if (!value.tetra) return value.key;
  return value.kind === 'stat' ? TETRA_PAIRS[tetra].stat : tetra;
}

interface BattleContext {
  conditionals: Record<string, boolean>;
  rolls: Record<string, number>;
  level: number;
  /** Set pieces equipped; thresholds above it don't apply. */
  pieces?: number;
}

function bonusesForItem(
  itemName: string | null | undefined,
  effects: ItemEffect[],
  ul: number,
  into: ItemBonuses,
  context: BattleContext,
  tetra?: TetraAlignment,
): ItemBonuses {
  if (!itemName) return into;
  effects.forEach((effect, index) => {
    if (effect.applies === 'reference') return;
    if (effect.count && effect.count > (context.pieces ?? 0)) return;
    if (effect.applies === 'conditional' && !context.conditionals[itemConditionalKey(itemName, index)]) return;
    effect.effects.forEach((value, valueIndex) => {
      const amount = valueAtUL(value, ul, context.rolls[itemRollKey(itemName, index, valueIndex)], context.level, context.pieces);
      if (!amount) return;
      const valueKey = effectKey(value, tetra);
      if (value.kind === 'setStat') {
        const key = valueKey as StatKey;
        into.setStats[key] = Math.max(into.setStats[key] ?? -Infinity, amount);
      } else if (value.kind === 'buffStat') {
        const key = `buff:${valueKey}`;
        into.derived[key] = (into.derived[key] ?? 0) + amount;
      } else if (value.kind === 'stat') {
        const key = valueKey as StatKey;
        into.stats[key] = (into.stats[key] ?? 0) + amount;
      } else if (value.kind === 'elementalAttack') {
        const key = valueKey as ElementKey;
        into.elementalAttack[key] = (into.elementalAttack[key] ?? 0) + amount;
      } else if (value.kind === 'resistance') {
        const key = valueKey as ResistKey;
        into.resistances[key] = (into.resistances[key] ?? 0) + amount;
      } else {
        into.derived[valueKey] = (into.derived[valueKey] ?? 0) + amount;
      }
    });
  });
  return into;
}

export interface GearSlotInput {
  itemName?: string | null;
  /** `object`, not `Record<string, number>`: the per-slot interfaces have no index signature. */
  upgradePoints?: object;
  tetra?: TetraAlignment;
}

export function gearUL(points: object | undefined): number {
  if (!points) return 0;
  return Object.values(points).reduce<number>((total, value) => total + (Number(value) || 0), 0);
}

export function itemBonuses(input: {
  weaponName?: string | null;
  armorName?: string | null;
  weaponPoints?: WeaponUpgradePoints;
  armorPoints?: ArmorUpgradePoints;
  gear?: Array<GearSlotInput | undefined>;
  conditionals?: Record<string, boolean>;
  rolls?: Record<string, number>;
  level?: number;
  sets?: ActiveSetPieces[];
}): ItemBonuses {
  const weapons = weaponEffects(input.weaponName);
  const armors = armorEffects(input.armorName);
  const gear = input.gear;
  let hasGear = false;
  if (gear) {
    for (const slot of gear) {
      if (slot?.itemName && gearEffects(slot.itemName).length) { hasGear = true; break; }
    }
  }
  const sets = (input.sets ?? []).filter(set => setEffects(set.name).length);
  if (!weapons.length && !armors.length && !hasGear && !sets.length) return EMPTY;

  const context = { conditionals: input.conditionals ?? {}, rolls: input.rolls ?? NO_ROLLS, level: input.level ?? 0 };
  const result: ItemBonuses = { stats: {}, setStats: {}, derived: {}, elementalAttack: {}, resistances: {} };
  bonusesForItem(input.weaponName, weapons, weaponUL(input.weaponPoints), result, context);
  bonusesForItem(input.armorName, armors, armorUL(input.armorPoints), result, context);
  if (gear) {
    for (const slot of gear) {
      if (!slot?.itemName) continue;
      const effects = gearEffects(slot.itemName);
      if (!effects.length) continue;
      bonusesForItem(slot.itemName, effects, gearUL(slot.upgradePoints), result, context, slot.tetra);
    }
  }
  for (const set of sets) bonusesForItem(set.name, setEffects(set.name), 0, result, { ...context, pieces: set.pieces });
  return result;
}

export interface ActiveSetPieces {
  name: string;
  pieces: number;
}

export interface SetAttackEffect {
  label: string;
  damagePercent?: number;
  resistanceIgnored?: { types: string[]; percent: number };
}

/** Reached set thresholds that change the damage you deal (Unassuming Adventurer, Gunsmoke Spiritual). */
export function setAttackEffects(sets: ActiveSetPieces[]): SetAttackEffect[] {
  return sets.flatMap(set => setEffects(set.name)
    .filter(effect => (effect.count ?? 0) <= set.pieces && (effect.damagePercent || effect.resistanceIgnored))
    .map(effect => ({
      label: `${set.name} ${effect.count}+`,
      ...(effect.damagePercent ? { damagePercent: effect.damagePercent } : {}),
      ...(effect.resistanceIgnored ? { resistanceIgnored: effect.resistanceIgnored } : {}),
    })));
}
